"use strict";(globalThis.webpackChunkuniwahl_doku||=[]).push([[9597],{3185(e,n,i){i.r(n),i.d(n,{assets:()=>h,contentTitle:()=>a,default:()=>o,frontMatter:()=>l,metadata:()=>r,toc:()=>d});const r=JSON.parse('{"id":"releases/7.0","title":"Version 7.0","description":"\ud83d\ude80Dieses Release bringt eine modernisierte Benutzeroberfl\xe4che sowie mehr Flexibilit\xe4t in der Darstellung komplexer Wahlordnungen.","source":"@site/docs/releases/7.0.md","sourceDirName":"releases","slug":"/releases/7.0","permalink":"/uniwahl-doku/pr-preview/pr-5/releases/7.0","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Version 7.0"},"sidebar":"doku","previous":{"title":"Version 7.0.3","permalink":"/uniwahl-doku/pr-preview/pr-5/releases/7.0.3"},"next":{"title":"Version 6.5","permalink":"/uniwahl-doku/pr-preview/pr-5/releases/6.5"}}');var t=i(4848),s=i(8453);const l={title:"Version 7.0"},a=void 0,h={},d=[];function u(e){const n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.p,{children:"\ud83d\ude80Dieses Release bringt eine modernisierte Benutzeroberfl\xe4che sowie mehr Flexibilit\xe4t in der Darstellung komplexer Wahlordnungen."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Modernisierung der Benutzeroberfl\xe4che"}),(0,t.jsx)("br",{}),"Das Benutzerinterface wurde optisch und funktional \xfcberarbeitet. Ein hellerer Mittelbereich mit wei\xdfem Hintergrund lenkt den Blick gezielter auf die eigentlichen Inhalte. Mehr Abstand zwischen Zeilen und Elementen schafft mehr \xdcbersicht, besonders bei langen Listen oder umfangreichen Kandidatenansichten. Statt dichter, grauer Fl\xe4chen sehen Sie eine leichtere Darstellung mit klaren Kontrasten. Das erleichtert das Lesen und minimiert Erm\xfcdung bei l\xe4ngerer Arbeit. Die Werkzeugleiste wurde mit Schriften erg\xe4nzt und die Kopfzeile der Wahlbereiche ist mit Statusinformation nun visuell noch klarer getrennt und vermittelt so auf einen Blick den Bearbeitungsstand. Die Schriftgr\xf6\xdfe wurde erh\xf6ht und auch die Anordnung der Listen und Kandidierenden ist nun gleichm\xe4\xdfiger, was die Orientierung beim Z\xe4hlen erleichtert. Insgesamt entsteht ein modernisierter, aufger\xe4umter Eindruck. Buttons und Aktionen wurden st\xe4rker gewichtet. Wichtige Schaltfl\xe4chen wurden direkt im Wahlbereich hinzugef\xfcgt, wodurch typische Bedienfehler vermieden werden. Gleichzeitig zeigt die Statusleiste relevante Informationen wie den Dateispeicherort direkt an. Sie wissen so jederzeit, in welcher Datei Sie gerade arbeiten."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Wahlordnung \u2013 Wahlbereiche verbinden (nur Online-Wahl)"}),(0,t.jsx)("br",{}),"Bei Online-Wahlen erm\xf6glicht es die neue Funktion \u201eWahlbereiche verbinden\u201c, mehrere Wahlbereiche in einer gemeinsamen, durchg\xe4ngigen Ansicht darzustellen \u2013 typischerweise bei Szenarien wie \u201ealle w\xe4hlen alles\u201c oder bei kombinierter Wahl (Bsp. Vertreter und Stellvertreter, m\xe4nnliche und weibliche Vertretung). Statt dass W\xe4hler nacheinander zwischen einzelnen digitalen Stimmzetteln wechseln m\xfcssen, werden diese nun logisch auf einer Seite geb\xfcndelt. Die Darstellung bleibt regelkonform getrennt, wird aber als zusammenh\xe4ngender Wahlvorgang erlebt. F\xfcr W\xe4hlende entsteht ein klar strukturierter Wahlablauf ohne unn\xf6tige Seitenwechsel. Das reduziert Abbr\xfcche, R\xfcckfragen und Korrekturen, erh\xf6ht die Vollst\xe4ndigkeit der Stimmabgaben und sorgt f\xfcr eine ruhigere Durchf\xfchrung der Wahl."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Wahlordnung \u2013 Nachr\xfccker manuell losen"}),(0,t.jsx)("br",{}),"Wenn bei der Auswertung der Wahl eine Stimmengleichheit auftritt, kann das vorgeschriebene Losverfahren nun vollst\xe4ndig manuell durchgef\xfchrt werden. Die neue Funktion \u201eNachr\xfccker manuell losen\u201c in uniWAHL erm\xf6glicht es, auch Nachr\xfccker f\xfcr Wahlgremien oder Listenpl\xe4tze nicht nur automatisch, sondern gezielt und kontrolliert per Los zu bestimmen. Das adressiert Situationen, in denen eine rein automatische Berechnung nicht den organisatorischen bzw. rechtlichen Anforderungen gen\xfcgt."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Wahlordnung \u2013 Sitze pro Liste / Grundmandate"}),(0,t.jsx)("br",{}),"Diese Funktion erlaubt es Ihnen, sitz- und mandatsbezogene Regelungen direkt entsprechend Ihrer Wahlordnung abzubilden. Sie ber\xfccksichtigt automatisch festgelegte Grundmandate oder Mindestsitze pro Liste. Sie definieren damit verbindlich, wie viele Sitze einer Liste mindestens zustehen oder welche Grundmandate unabh\xe4ngig vom rechnerischen Verteilverfahren garantiert sind. Diese Einstellungen werden einmal sauber hinterlegt und anschlie\xdfend automatisch in der Mandatsberechnung ber\xfccksichtigt. Das spart Zeit, verhindert Rechenfehler und sorgt f\xfcr eine regelkonforme Mandatsvergabe ohne manuelle Nacharbeit. \u201eSitze pro Liste\u201c funktioniert auch in Kombination mit der Wahlordnungsoption \u201eMehrheitswahl auch bei mehreren Listen m\xf6glich\u201c, dadurch werden zahlreiche Konstellationen unterst\xfctzt, die in realen Wahlordnungen vorgesehen sind."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Wahlordnung \u2013 Feste Anzahl von Ersatzmitgliedern"}),(0,t.jsx)("br",{}),"Gremien sollten handlungsf\xe4hig, rechtssicher und repr\xe4sentativ bleiben, auch wenn sich personelle Ver\xe4nderungen ergeben. In vielen Wahlordnungen langfristiger Vertretungen (Mitarbeitervertretungen, Kammern, Genossenschaften u.a.) existiert daher eine praktische Balance: genug Ersatzvertretungen, um Ausf\xe4lle abzufangen, aber begrenzt, damit die Zusammensetzung des Gremiums nicht \xfcber das notwendige Ma\xdf hinausw\xe4chst. Mit dieser Funktion legen Sie bereits vor der Wahl fest, wie viele Ersatzmitglieder automatisch ermittelt werden sollen. Die Nachr\xfcckreihenfolge ergibt sich direkt aus dem Wahlergebnis. Das schafft klare Verh\xe4ltnisse, reduziert manuellen Aufwand und vermeidet Unklarheiten beim sp\xe4teren Nachr\xfccken von Mitgliedern."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Layout-Verzeichnisse zentral verwalten"}),(0,t.jsx)("br",{}),"Ein h\xe4ufiges Problem in Wahlprojekten ist die Versionsvielfalt der Layouts. Unterschiedliche Bearbeitungsst\xe4nde in den Wahlbereichen f\xfchrten schnell zu falschen Ausgaben bzw. unn\xf6tigen Korrekturschleifen. Die zentrale Verwaltung der Layoutverzeichnisse beseitigt diese Unsicherheit. Es kann nun mit weniger Layouts \xfcber alle Wahlbereiche hinweg gearbeitet werden. Die Funktion \u201eLayout-Verzeichnisse\u201c b\xfcndelt alle Einstellungen zu Drucklayouts, Online-Wahlkabine und Dokumentdesigns an einer gemeinsamen Stelle. Statt Layouts lokal in Dateien zu speichern, werden sie nun in einem zentralen Verzeichnis innerhalb von uniWAHL abgelegt und gespeichert. Bisherige Layouts lassen sich nahtlos weiterverwenden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Unerlaubte Zus\xe4tze als \u201eung\xfcltig\u201c behandeln (uniSCAN)"}),(0,t.jsx)("br",{}),"Die Funktion \u201eUnerlaubte Zus\xe4tze suchen\u201c pr\xfcft gescannte Stimmzettel seit L\xe4ngerem automatisch auf unerlaubte Zus\xe4tze wie Kommentare oder zus\xe4tzliche Markierungen und markiert die erkannten Stimmzettel als \u201eWarnung\u201c. Werden solche Zus\xe4tze erkannt, kann nun auch entschieden werden, ob die Stimme regelkonform direkt als ung\xfcltig gewertet wird. Das reduziert den manuellen Nachbearbeitungsaufwand anhand der uniSCAN Ausz\xe4hlungsprotokolle erheblich und erm\xf6glicht ung\xfcltige Stimmzettel durch Zus\xe4tze des Wahlvorstands wie Pr\xfcfstempel oder Signaturen w\xe4hrend des Scan zu separieren."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Wahlberechtigte z\xe4hlen (Alle Bereiche)"}),(0,t.jsx)("br",{}),"Mit der Funktion \u201eWahlberechtigte z\xe4hlen (Alle Bereiche)\u201c ermittelt das System automatisch alle registrierten Wahlberechtigten \xfcber alle vorhandenen Wahlbereiche anhand der W\xe4hlergruppen-Kodierung. Sie sehen anschlie\xdfend den Wert und k\xf6nnen diese Zahl zur Erstellung des Wahlergebnis (Wahlbeteiligungsquote) oder f\xfcr statistische Auswertungen nutzen. Manuelle Zusammenz\xe4hlungen, die h\xe4ufig fehleranf\xe4llig und zeitaufwendig sind, entfallen somit vollst\xe4ndig."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:'Wahlergebnis \u2013 Spalte "Rang"'}),(0,t.jsx)("br",{}),"Das Layout des Wahlergebnis wird um eine optionale, zus\xe4tzliche Rang-Spalte erg\xe4nzt, die die Platzierung aller Kandidierenden automatisch ausweist. Im Wahlergebnis ist damit klarer erkennbar, wer welchen Rang erreicht hat. Die Reihenfolge ergibt sich wie gewohnt aus den berechneten Mandaten und wird unmittelbar im Wahlergebnis dargestellt. Ergebnisse lassen sich dadurch schneller pr\xfcfen, dokumentieren und kommunizieren."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Variable Listenarten (uniWAHL OWS)"}),(0,t.jsx)("br",{}),"Die Erweiterung stellt sicher, dass variable Listenarten pro Gruppe nicht nur in uniWAHL konfiguriert, sondern auch an das Online-Wahlsystem \xfcbergeben werden k\xf6nnen. Sobald Sie in der Wahlordnung unterschiedliche Listenarten je Gruppe definieren, \xfcbernimmt das System diese Struktur automatisch in die Online-Umgebung. Die in uniWAHL getroffene fachliche Entscheidung bleibt damit technisch konsistent bis zur Online-Stimmabgabe erhalten."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsxs)(n.strong,{children:["Tabelle aller Kandidat",":innen"," (Reimport, Serienbrief)"]}),(0,t.jsx)("br",{}),"Die \xfcberarbeitete Funktion \u201eTabelle aller Kandidat",":innen","\u201c macht den Export und die erneute \xdcbernahme von Wahlvorschl\xe4gen zu einem durchg\xe4ngigen Arbeitsprozess. Sie k\xf6nnen nun s\xe4mtliche Kandidierenden \xfcber die Ausgabe > \u201eTabelle aller Kandidat",":innen","\u201c als XLSX-Datei exportieren, zentral \xfcberarbeiten und anschlie\xdfend wieder importieren. Die Datei enth\xe4lt das Wahlbereichsk\xfcrzel, sodass jede Person eindeutig ihrer Gruppe zugeordnet bleibt. Auch Gruppen im Status 2 werden ber\xfccksichtigt, wodurch sich vollst\xe4ndige Wahlvorschlagslisten ohne Umwege bearbeiten lassen. Im praktischen Einsatz ist das besonders hilfreich, wenn nachtr\xe4glich Erg\xe4nzungen n\xf6tig sind, etwa bei fehlenden Zus\xe4tzen, korrigierten Angaben oder nachgereichten Vertretungen. Sie exportieren die Gesamtliste, passen die Daten gesammelt in Excel an und importieren sie wieder in uniWAHL. Zus\xe4tzlich enth\xe4lt die Tabelle jetzt den Personenstatus, also ob jemand gew\xe4hlt oder nicht gew\xe4hlt ist. Damit bleibt der inhaltliche Stand jederzeit transparent und die Liste kann zur Erzeugung von Serienbriefen genutzt werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Alle Kandidaten entfernen (jetzt ohne Wahlverfahren)"}),(0,t.jsx)("br",{}),"Die \xfcberarbeitete Funktion > \u201eAlle Kandidat",":innen"," entfernen\u201c erm\xf6glicht es nun, Wahlbereiche schnell zur\xfcckzusetzen, ohne die grundlegende Konfiguration zu verlieren. Beim Leeren eines Wahlbereichs werden s\xe4mtliche Kandidierenden entfernt, w\xe4hrend das hinterlegte Wahlverfahren jedoch unver\xe4ndert bestehen bleibt. Die Struktur der Wahl kann dadurch direkt wiederverwendet werden. In der Anwendung ist das besonders praktisch bei j\xe4hrlich wiederkehrenden Wahlen mit \xe4hnlichem Verfahren. Sie setzen die bestehenden Bereiche zur\xfcck und k\xf6nnen sofort neue Wahlvorschl\xe4ge importieren oder erfassen, ohne das Verfahren erneut konfigurieren zu m\xfcssen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Mehrfachselektion im Navigator"}),(0,t.jsx)("br",{}),"Diese erweitert die bekannten Aktionen \u2013 im Kontextmen\xfc des Navigationsbereichs \u2013 wie Kopieren, Einf\xfcgen oder Entfernen auf mehrere Elemente gleichzeitig. Sie k\xf6nnen im Navigator nun mehrere Eintr\xe4ge markieren und in einem Schritt bearbeiten. In der Praxis w\xe4hlen Sie einfach die gew\xfcnschten Eintr\xe4ge per Mehrfachauswahl aus und f\xfchren anschlie\xdfend die gew\xfcnschte Aktion aus. Wenn regelm\xe4\xdfig identische Strukturen ben\xf6tigt werden, etwa vier gleich aufgebaute Statusgruppen, k\xf6nnen diese nun in einem einzigen Vorgang kopiert werden. Das spart wiederholte Klicks und sorgt f\xfcr einen fl\xfcssigen Arbeitsablauf bei der Vorbereitung komplexer Wahlstrukturen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Mehr Buttons direkt im Wahlbereich"}),(0,t.jsx)("br",{}),"Am unteren Rand jedes Wahlbereichs stehen nun direkte Schaltfl\xe4chen f\xfcr Wahlvorschl\xe4ge, Stimmzettel, Online-Wahl und Wahlergebnis zur Verf\xfcgung. Jede Vorschau wird automatisch nur f\xfcr den aktuell ausgew\xe4hlten Bereich erzeugt, ohne dass Sie erst in \xfcbergeordnete Men\xfcs wechseln m\xfcssen. Im t\xe4glichen Einsatz beschleunigt das die Kontrolle einzelner Bereiche erheblich. Sie k\xf6nnen w\xe4hrend der Konfiguration sofort pr\xfcfen, wie Wahlvorschl\xe4ge erscheinen, ob der Stimmzettel korrekt aufgebaut ist oder wie die Daten f\xfcr die Online-Wahl aussehen. Auch Zwischenergebnisse lassen sich gezielt pro Bereich anzeigen. Die R\xfcckmeldung erfolgt unmittelbar im Arbeitskontext."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Layout / Texte aus Verzeichnissen direkt in Wahlbereich \xfcbernehmen"}),(0,t.jsx)("br",{}),"Ein h\xe4ufiges Problem bestand darin, dass Layout- und Textquellen zwar vorhanden, aber umst\xe4ndlich erreichbar waren. Das f\xfchrte zu lokalen Zwischenl\xf6sungen oder versehentlich veralteten Inhalten. Durch die sichtbare Platzierung im Wahlbereich wird die Nutzung der zentralen Verzeichnisse zum nat\xfcrlichen Arbeitsschritt. Diese Funktion macht die Verzeichnisse \u201eLayout\u201c bzw. \u201eTexte\u201c direkt im Wahlbereich sichtbar und b\xfcndelt sie in einem \xfcbersichtlichen Dropdown. Dar\xfcber k\xf6nnen Sie Layouts und Textvorlagen unmittelbar aus den hinterlegten Verzeichnissen in den aktuellen Wahlbereich \xfcbernehmen. Die Auswahl erfolgt kontextbezogen, ohne dass zus\xe4tzliche Dialoge ge\xf6ffnet oder globale Einstellungen durchsucht werden m\xfcssen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsxs)(n.strong,{children:["Erh\xf6hung der Kandidat",":innenfelder"]}),(0,t.jsx)("br",{}),"Es stehen in den Layouts jetzt 7 Felder f\xfcr Personendaten zur Verf\xfcgung. Die Funktion erweitert die verf\xfcgbaren Datenfelder in Stimmzetteln, Wahlvorschl\xe4gen und Wahlergebnissen. Pro Kandidat",":in"," k\xf6nnen nun mehr Informationen dargestellt werden, ohne auf externe Listen oder Zusatzdokumente ausweichen zu m\xfcssen. Die zus\xe4tzlichen Felder stehen direkt in den bekannten Ausgaben zur Verf\xfcgung und lassen sich wie gewohnt bef\xfcllen. In der Anwendung profitieren Sie \xfcberall dort, wo Kandidierende mit erweiterten Angaben gef\xfchrt werden, etwa mit Funktionen, Fachbereichen, Zus\xe4tzen oder Vertretungsinformationen."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"\u2699\ufe0fWeitere \xc4nderungen und Fehlerbehebungen"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Die Vorschau der Online-Wahlkabine wurde technisch weiter stabilisiert und verbessert."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Das uniSCAN-Panel \xf6ffnete sich in bestimmten Situationen nicht mehr automatisch. Dieses Verhalten wurde korrigiert."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Die Online-Vorschau funktionierte nicht korrekt in Kombination mit einem footerHTML-Element. Das Problem wurde behoben, sodass Inhalte nun wie erwartet angezeigt werden."}),"\n",(0,t.jsx)(n.li,{children:"\u2705 Das Fehlerhandling bei Bild-URLs wurde verbessert, um fehlerhafte oder nicht erreichbare Bildquellen robuster abzufangen."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Sonderzeichen in Gremien-K\xfcrzeln konnten zu Verarbeitungsproblemen f\xfchren. Diese werden nun herausgefiltert."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Die Datei result.xml konnte unter bestimmten Umst\xe4nden von uniSCAN nicht \xfcberschrieben werden. Dieses Problem wurde behoben."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Bestimmte Tastenk\xfcrzel f\xfchrten zu unerwartetem Verhalten. Die Tastenk\xfcrzel wurden systemweit entfernt und neu zugeordnet."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e In der Funktion \u201eFeldbezeichner bearbeiten\u201c konnte ein leerer Text angezeigt werden. Die Anzeige wurde korrigiert."}),"\n",(0,t.jsx)(n.li,{children:"\u2705 Beim Import wurden Feldbezeichner bislang nicht auf bestimmte Sonderzeichen gepr\xfcft. Eine entsprechende Validierung wurde erg\xe4nzt."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Bei der Wahlverzeichnis-Pr\xfcfung kam es zu einem CSS-Darstellungsfehler. Dieser wurde behoben."}),"\n",(0,t.jsxs)(n.li,{children:["\ud83d\udc1e Beim \u201eEntfernen aller Kandidat",":innen","\u201c wurden f\xe4lschlicherweise eingegebene, variable Stimmen gel\xf6scht. Dieses Verhalten wurde korrigiert."]}),"\n",(0,t.jsx)(n.li,{children:"\u2705 Der zul\xe4ssige Wertebereich f\xfcr erzeugte PIN/TANs wurde eingeschr\xe4nkt, um fehlerhafte Eingaben seitens der W\xe4hlenden zu vermeiden (\u201e0\u201c und \u201eO\u201c, \u201eI\u201c und \u201el\u201c)."}),"\n",(0,t.jsx)(n.li,{children:"\u2705 Das Fehlerhandling bei Kandidatenfeldern wurde verbessert, um ung\xfcltige Eingaben fr\xfchzeitig abzufangen."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Wahlkennungen mit Buchstaben f\xfchrten zu Problemen in der Verarbeitung. Diese werden nun korrekt unterst\xfctzt."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Beim Import der Kandidierenden wurde die Wahlordnung in bestimmten F\xe4llen ignoriert (alphabetische Reihung u.a.). Die Wahlbereiche werden nun im Status 2 importiert."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Beim Stimmenimport wurde der Status des Wahlbereichs nicht aktualisiert. Dieses Verhalten wurde korrigiert."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e In den Dateiausgaben zur Benachrichtigung wurden Felder teilweise doppelt ausgegeben. Die doppelte Anzeige wurde behoben."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Die Lizenz konnte unter bestimmten Bedingungen zu fr\xfch als abgelaufen markiert werden. Dieses Problem wurde behoben."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1e Bei Erst- und Zweitstimmen wurden bereits gew\xe4hlte Kandidaten nicht korrekt unabh\xe4ngig von der Sitzverteilung ber\xfccksichtigt. Die Logik wurde korrigiert."}),"\n",(0,t.jsx)(n.li,{children:"\u2705 Die Funktion \u201eWahlberechtigte z\xe4hlen (Alle Bereiche)\u201c verursachte unn\xf6tigen Speicherbedarf. Die Speicherverwendung wurde optimiert."}),"\n",(0,t.jsx)(n.li,{children:"\u2705 Die Funktion \u201eUng\xfcltig w\xe4hlen oben platzieren\u201c f\xfcr Online-Wahlen war ohne Funktion und wurde entfernt."}),"\n",(0,t.jsx)(n.li,{children:"\u2705 Die Funktion \u201ePermanente SmartLinks ausgeben\u201c erlaubt das Vorab-Erzeugen permanenter Links, um SmartLink-Logik und W\xe4hlergruppen fr\xfchzeitig zu testen und Konfigurationsfehler schneller zu erkennen."}),"\n"]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(u,{...e})}):u(e)}},8453(e,n,i){i.d(n,{R:()=>l,x:()=>a});var r=i(6540);const t={},s=r.createContext(t);function l(e){const n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:l(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);